import { useState, useEffect, useCallback } from 'react';
import api from '../services/api';

// 随机排序函数
const shuffleArray = (array) => {
  const shuffled = [...array];
  for (let i = shuffled.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]];
  }
  return shuffled;
};

export const useVideos = () => {
  const [videos, setVideos] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [hasMore, setHasMore] = useState(true);
  const [page, setPage] = useState(1);
  const [scrollPosition, setScrollPosition] = useState(0);

  // 获取视频列表
  const fetchVideos = useCallback(async (refresh = false) => {
    try {
      setLoading(true);
      setError(null);
      
      const currentPage = refresh ? 1 : page;
      const response = await api.getVideos(currentPage, 20);
      
      if (refresh) {
        // 刷新时随机排序
        const shuffledVideos = shuffleArray(response);
        setVideos(shuffledVideos);
        setPage(1);
      } else {
        setVideos(prev => [...prev, ...response]);
        setPage(prev => prev + 1);
      }
      
      // 如果返回的数据少于20条，说明没有更多数据了
      setHasMore(response.length === 20);
    } catch (err) {
      setError(err.message);
      console.error('Failed to fetch videos:', err);
    } finally {
      setLoading(false);
    }
  }, [page]);

  // 刷新视频列表
  const refreshVideos = useCallback(() => {
    return fetchVideos(true);
  }, [fetchVideos]);

  // 加载更多视频
  const loadMore = useCallback(() => {
    if (!loading && hasMore) {
      fetchVideos();
    }
  }, [loading, hasMore, fetchVideos]);

  // 更新播放量
  const updateVideoViews = useCallback(async (videoId) => {
    try {
      await api.updateViews(videoId);
      // 更新本地视频列表中的播放量
      setVideos(prev => prev.map(video => 
        video.id === videoId 
          ? { ...video, view_count: (parseInt(video.view_count) + 1).toString() }
          : video
      ));
    } catch (err) {
      console.error('Failed to update views:', err);
    }
  }, []);

  // 保存滚动位置
  const saveScrollPosition = useCallback((position) => {
    setScrollPosition(position);
  }, []);

  // 恢复滚动位置
  const restoreScrollPosition = useCallback((scrollElement) => {
    if (scrollElement && scrollPosition > 0) {
      scrollElement.scrollTop = scrollPosition;
    }
  }, [scrollPosition]);

  // 初始化加载
  useEffect(() => {
    fetchVideos(true);
  }, []);

  // 检查是否需要刷新列表（从视频播放页面返回时不刷新）
  const shouldRefreshOnMount = () => {
    // 检查是否有保存的滚动位置，如果有说明之前有数据，不需要刷新
    return scrollPosition === 0;
  };

  return {
    videos,
    loading,
    error,
    hasMore,
    refreshVideos,
    loadMore,
    updateVideoViews,
    saveScrollPosition,
    restoreScrollPosition,
    shouldRefreshOnMount,
  };
}; 