import React, { useRef, useEffect, useState } from 'react';
import { useParams, useNavigate, useLocation } from 'react-router-dom';
import { useSwipeable } from 'react-swipeable';
import videojs from 'video.js';
import 'video.js/dist/video-js.css';
import api from '../services/api';
import './VideoPlayerPage.css';

const VideoPlayerPage = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const location = useLocation();
  const videoRef = useRef(null);
  const playerRef = useRef(null);
  const [video, setVideo] = useState(location.state?.video || null);
  const [loading, setLoading] = useState(!location.state?.video);
  const [error, setError] = useState(null);
  const [allVideos, setAllVideos] = useState([]);
  const [currentIndex, setCurrentIndex] = useState(0);
  const [isLoadingMore, setIsLoadingMore] = useState(false);

  // 获取所有视频列表和当前视频信息
  useEffect(() => {
    const fetchData = async () => {
      try {
        setLoading(true);
        
        // 获取所有视频列表 - 增加数量以确保有足够视频
        const videosList = await api.getVideos(1, 200); // 获取前200个视频
        setAllVideos(videosList);
        
        // 找到当前视频的索引
        const currentVideoIndex = videosList.findIndex(v => v.id === parseInt(id));
        setCurrentIndex(currentVideoIndex >= 0 ? currentVideoIndex : 0);
        
        // 如果没有从路由状态获取到视频信息，则从API获取当前视频
        if (!location.state?.video) {
          const videoData = await api.getVideo(id);
          setVideo(videoData);
        } else {
          setVideo(location.state.video);
        }
      } catch (err) {
        console.error('Failed to fetch data:', err);
        setError(err.message);
      } finally {
        setLoading(false);
      }
    };
    
    fetchData();
  }, [id, location.state]);

  useEffect(() => {
    if (!video) return;

    let timeout;
    if (videoRef.current) {
      timeout = setTimeout(() => {
        // 🆕 优化播放器配置，支持自动播放
        const playerOptions = {
          controls: true,
          responsive: true,
          fluid: true,
          preload: 'metadata', // 预加载元数据
          autoplay: true, // 🆕 启用自动播放
          muted: true, // 🆕 静音播放（浏览器策略要求）
          sources: [{ 
            src: video.video_url, 
            type: video.video_url?.includes('.m3u8') ? 'application/x-mpegURL' : 'video/mp4' 
          }],
          controlBar: {
            children: [
              'playToggle',
              'volumePanel',
              'currentTimeDisplay',
              'timeDivider',
              'durationDisplay',
              'progressControl',
              'remainingTimeDisplay',
              'fullscreenToggle'
            ]
          }
        };

        playerRef.current = videojs(videoRef.current, playerOptions);

        // 🆕 添加事件监听
        playerRef.current.on('loadstart', () => {
          console.log('🎬 开始加载视频');
        });

        playerRef.current.on('loadedmetadata', () => {
          console.log('📋 视频元数据加载完成');
        });

        playerRef.current.on('canplay', () => {
          console.log('✅ 视频可以开始播放');
          // 🆕 自动开始播放
          if (playerRef.current.paused()) {
            playerRef.current.play().catch(error => {
              console.log('⚠️ 自动播放失败，可能需要用户交互:', error);
            });
          }
        });

        playerRef.current.on('waiting', () => {
          console.log('⏳ 视频缓冲中...');
        });

        playerRef.current.on('error', (error) => {
          console.error('❌ 播放错误:', error);
        });

        // 🆕 播放开始后取消静音
        playerRef.current.on('play', () => {
          console.log('▶️ 视频开始播放');
          // 延迟取消静音，确保播放已经开始
          setTimeout(() => {
            if (playerRef.current && !playerRef.current.paused()) {
              playerRef.current.muted(false);
              console.log('🔊 已取消静音');
            }
          }, 100);
        });

      }, 0);
    }
    return () => {
      if (timeout) clearTimeout(timeout);
      if (playerRef.current) {
        playerRef.current.dispose();
      }
    };
  }, [video]);

  // 动态加载更多视频
  const loadMoreVideos = async () => {
    if (isLoadingMore) return;
    
    try {
      setIsLoadingMore(true);
      console.log('📥 正在加载更多视频...');
      
      // 获取更多视频
      const moreVideos = await api.getVideos(2, 100); // 获取第2页的100个视频
      
      if (moreVideos.length > 0) {
        setAllVideos(prev => [...prev, ...moreVideos]);
        console.log(`✅ 成功加载 ${moreVideos.length} 个新视频，总计 ${allVideos.length + moreVideos.length} 个`);
      }
    } catch (err) {
      console.error('❌ 加载更多视频失败:', err);
    } finally {
      setIsLoadingMore(false);
    }
  };

  // 切换到下一个视频
  const switchToNextVideo = async () => {
    console.log('🔄 尝试切换到下一个视频', { currentIndex, totalVideos: allVideos.length });
    
    if (allVideos.length === 0) {
      console.log('❌ 视频列表为空');
      return;
    }
    
    // 如果接近列表末尾，尝试加载更多视频
    if (currentIndex >= allVideos.length - 5 && !isLoadingMore) {
      await loadMoreVideos();
    }
    
    // 计算下一个索引，支持循环播放
    const nextIndex = (currentIndex + 1) % allVideos.length;
    const nextVideo = allVideos[nextIndex];
    
    console.log('✅ 切换到下一个视频:', { 
      from: currentIndex, 
      to: nextIndex, 
      videoId: nextVideo.id, 
      title: nextVideo.title 
    });
    
    setCurrentIndex(nextIndex);
    setVideo(nextVideo);
    
    // 更新URL但不刷新页面
    navigate(`/video/${nextVideo.id}`, { 
      state: { video: nextVideo },
      replace: true 
    });
  };

  // 切换到上一个视频
  const switchToPreviousVideo = () => {
    console.log('🔄 尝试切换到上一个视频', { currentIndex, totalVideos: allVideos.length });
    
    if (allVideos.length === 0) {
      console.log('❌ 视频列表为空');
      return;
    }
    
    // 计算上一个索引，支持循环播放
    const prevIndex = currentIndex === 0 ? allVideos.length - 1 : currentIndex - 1;
    const prevVideo = allVideos[prevIndex];
    
    console.log('✅ 切换到上一个视频:', { 
      from: currentIndex, 
      to: prevIndex, 
      videoId: prevVideo.id, 
      title: prevVideo.title 
    });
    
    setCurrentIndex(prevIndex);
    setVideo(prevVideo);
    
    // 更新URL但不刷新页面
    navigate(`/video/${prevVideo.id}`, { 
      state: { video: prevVideo },
      replace: true 
    });
  };

  // 配置滑动事件
  const swipeHandlers = useSwipeable({
    onSwipedUp: () => {
      console.log('👆 向上滑动 - 切换到下一个视频');
      switchToNextVideo();
    },
    onSwipedDown: () => {
      console.log('👇 向下滑动 - 切换到上一个视频');
      switchToPreviousVideo();
    },
    trackMouse: true, // 支持鼠标拖拽
    preventDefaultTouchmoveEvent: false, // 允许默认的触摸滚动
    delta: 50, // 最小滑动距离
    preventScrollOnSwipe: false, // 不阻止滚动
    trackTouch: true, // 跟踪触摸
    rotationAngle: 0, // 不限制角度
  });

  const handleBack = () => {
    // 返回时保持滚动位置，不刷新列表
    navigate('/', { 
      state: { 
        preserveScroll: true,
        fromVideoPlayer: true 
      } 
    });
  };

  if (loading) {
    return (
      <div className="video-player-page">
        <header className="player-header">
          <div className="header-content">
            <button className="back-button" onClick={handleBack}>
              ←
            </button>
            <h1 className="video-title">加载中...</h1>
          </div>
        </header>
        <main className="video-container">
          <div className="loading-container">
            <div className="loading-spinner"></div>
            <p>正在加载视频...</p>
          </div>
        </main>
      </div>
    );
  }

  if (error) {
    return (
      <div className="video-player-page">
        <header className="player-header">
          <div className="header-content">
            <button className="back-button" onClick={handleBack}>
              ←
            </button>
            <h1 className="video-title">加载失败</h1>
          </div>
        </header>
        <main className="video-container">
          <div className="error-container">
            <p>加载视频失败: {error}</p>
            <button onClick={() => window.location.reload()}>重试</button>
          </div>
        </main>
      </div>
    );
  }

  return (
    <div className="video-player-page" {...swipeHandlers}>
      {/* 顶部导航栏 */}
      <header className="player-header">
        <div className="header-content">
          <button className="back-button" onClick={handleBack}>
            ←
          </button>
          <h1 className="video-title">{video?.title || '未命名视频'}</h1>
          <div className="video-counter">
            {currentIndex + 1} / {allVideos.length}
          </div>
        </div>
      </header>

      {/* 视频播放器 */}
      <main className="video-container">
        <div data-vjs-player>
          <video 
            ref={videoRef} 
            className="video-js vjs-big-play-centered vjs-theme-city"
          />
        </div>
        
        {/* 滑动提示 */}
        <div className="swipe-hints">
          <div className="swipe-hint swipe-hint-up">
            <span>👆 上滑播放下一个</span>
          </div>
          <div className="swipe-hint swipe-hint-down">
            <span>👇 下滑播放上一个</span>
          </div>
        </div>
      </main>
    </div>
  );
};

export default VideoPlayerPage; 